describe("SPEC-ADPNEO-005: Neo4j adapter: a consumer's spec host may transform seed values, and every seed value must be one Neo4j can store", () => {
  let h: Harness;
  beforeAll(async () => {
    h = await createHarness({ configPath: CONFIG_PATH, specPath: SPEC_PATH, cases: CASES });
  });
  afterAll(async () => {
    await h?.teardown(); // createHarness may have thrown: nothing to tear down
  });
  for (const c of CASES) {
    it(c.name, async () => {
      await h.runCase(c, INLINE);
    });
  }
});
